export const GUIDE_NETHERLANDS_ENTRIES = [
  { find: 'Buying from the Netherlands: NIE in Amsterdam', es: 'Comprar desde Países Bajos: NIE en Ámsterdam', fr: 'Acheter depuis les Pays-Bas : NIE à Amsterdam', de: 'Kauf aus den Niederlanden: NIE in Amsterdam', ru: 'Покупка из Нидерландов: NIE в Амстердаме', ar: 'الشراء من هولندا: NIE في أمستردام', nl: 'Kopen vanuit Nederland: NIE in Amsterdam', pl: 'Zakup z Holandii: NIE w Amsterdamie', sv: 'Köpa från Nederländerna: NIE i Amsterdam', no: 'Kjøpe fra Nederland: NIE i Amsterdam' },
  { find: 'Buying a Costa del Sol new-build from the Netherlands: where the NIE is applied for, what a representative needs, and which tax questions to take to a Dutch adviser.', es: 'Comprar una vivienda de obra nueva en la Costa del Sol desde los Países Bajos: dónde se solicita el NIE, qué necesita un representante y qué cuestiones fiscales plantear a un asesor neerlandés.', fr: 'Acheter un logement neuf sur la Costa del Sol depuis les Pays-Bas : où demander le NIE, ce dont un représentant a besoin et quelles questions fiscales soumettre à un conseiller néerlandais.', de: 'Neubau an der Costa del Sol aus den Niederlanden kaufen: wo die NIE beantragt wird, was ein Vertreter braucht und welche Steuerfragen Sie einem niederländischen Berater stellen sollten.', ru: 'Покупка новостройки на Коста-дель-Соль из Нидерландов: где подаётся заявление на NIE, что нужно представителю и какие налоговые вопросы стоит обсудить с нидерландским налоговым консультантом.', ar: 'شراء عقار جديد على ساحل كوستا ديل سول من هولندا: أين يُقدَّم طلب رقم NIE، وما الذي يحتاجه الممثّل، وما الأسئلة الضريبية التي ينبغي طرحها على مستشار ضريبي هولندي.', nl: 'Een nieuwbouwwoning aan de Costa del Sol kopen vanuit Nederland: waar het NIE wordt aangevraagd, wat een vertegenwoordiger nodig heeft en welke fiscale vragen u aan een Nederlandse belastingadviseur kunt voorleggen.', pl: 'Zakup nowej nieruchomości na Costa del Sol z Holandii: gdzie składa się wniosek o NIE, czego potrzebuje pełnomocnik i z jakimi pytaniami podatkowymi zwrócić się do holenderskiego doradcy.', sv: 'Köpa nyproduktion på Costa del Sol från Nederländerna: var NIE söks, vad ett ombud behöver och vilka skattefrågor som hör hemma hos en nederländsk rådgivare.', no: 'Kjøpe nybygg på Costa del Sol fra Nederland: hvor NIE søkes, hva en representant trenger, og hvilke skattespørsmål du bør ta med til en nederlandsk rådgiver.' },
  { find: 'Buying from the Netherlands · 2026 Guide', es: 'Comprar desde los Países Bajos · Guía 2026', fr: 'Acheter depuis les Pays-Bas · Guide 2026', de: 'Kauf aus den Niederlanden · Leitfaden 2026', ru: 'Покупка из Нидерландов · Руководство 2026', ar: 'الشراء من هولندا · دليل 2026', nl: 'Kopen vanuit Nederland · Gids 2026', pl: 'Zakup z Holandii · Przewodnik 2026', sv: 'Köpa från Nederländerna · Guide 2026', no: 'Kjøpe fra Nederland · Guide 2026' },
  { find: 'Buying from the Netherlands, <em>what is different</em>', es: 'Comprar desde los Países Bajos, <em>qué cambia</em>', fr: 'Acheter depuis les Pays-Bas, <em>ce qui change</em>', de: 'Kauf aus den Niederlanden, <em>was anders ist</em>', ru: 'Покупка из Нидерландов, <em>что отличается</em>', ar: 'الشراء من هولندا، <em>ما الذي يختلف</em>', nl: 'Kopen vanuit Nederland, <em>wat er anders is</em>', pl: 'Zakup z Holandii, <em>co wygląda inaczej</em>', sv: 'Köpa från Nederländerna, <em>det som skiljer sig</em>', no: 'Kjøpe fra Nederland, <em>det som er annerledes</em>' },
  { find: 'Most of a Costa del Sol purchase can be arranged from home. This page covers what is specific to a Dutch buyer: where the NIE is applied for, what a representative needs, and which tax questions belong with your own adviser.', es: 'La mayor parte de una compra en la Costa del Sol puede gestionarse desde casa. Esta página recoge lo propio de un comprador neerlandés: dónde se solicita el NIE, qué necesita un representante y qué cuestiones fiscales corresponden a su propio asesor.', fr: 'L’essentiel d’un achat sur la Costa del Sol peut s’organiser depuis chez vous. Cette page couvre ce qui est propre à un acheteur néerlandais : où l’on demande le NIE, ce dont un représentant a besoin et quelles questions fiscales relèvent de votre propre conseiller.', de: 'Der größte Teil eines Kaufs an der Costa del Sol lässt sich von zu Hause aus organisieren. Diese Seite behandelt, was für einen niederländischen Käufer besonders ist: wo die NIE beantragt wird, was ein Vertreter braucht und welche Steuerfragen zu Ihrem eigenen Berater gehören.', ru: 'Большую часть покупки на Коста-дель-Соль можно организовать, не выезжая из дома. Эта страница рассказывает о том, что специфично для покупателя из Нидерландов: где подаётся заявление на NIE, что нужно представителю и какие налоговые вопросы относятся к вашему собственному налоговому консультанту.', ar: 'يمكن ترتيب معظم عملية الشراء على ساحل كوستا ديل سول من بلدك. وتتناول هذه الصفحة ما يخصّ المشتري الهولندي: أين يُقدَّم طلب رقم NIE، وما الذي يحتاجه الممثّل، وما الأسئلة الضريبية التي مكانها عند مستشارك الضريبي الخاص.', nl: 'Het grootste deel van een aankoop aan de Costa del Sol kunt u vanuit huis regelen. Deze pagina behandelt wat specifiek is voor een Nederlandse koper: waar het NIE wordt aangevraagd, wat een vertegenwoordiger nodig heeft en welke fiscale vragen bij uw eigen belastingadviseur thuishoren.', pl: 'Większość zakupu na Costa del Sol można załatwić z domu. Ta strona omawia to, co dotyczy kupującego z Holandii: gdzie składa się wniosek o NIE, czego potrzebuje pełnomocnik i które pytania podatkowe należy kierować do Państwa własnego doradcy.', sv: 'Det mesta av ett köp på Costa del Sol kan ordnas hemifrån. Den här sidan tar upp det som gäller en nederländsk köpare: var NIE söks, vad ett ombud behöver och vilka skattefrågor som hör hemma hos er egen rådgivare.', no: 'Det meste av et kjøp på Costa del Sol kan ordnes hjemmefra. Denne siden tar for seg det som gjelder en nederlandsk kjøper: hvor NIE søkes, hva en representant trenger, og hvilke skattespørsmål som hører hjemme hos din egen rådgiver.' },
  { find: 'Comparing projects, floorplans and payment schedules, even a private presentation of a development, all happen remotely. The parts that involve the Spanish state are a tax number, a power of attorney and the origin of your funds, and our general guide to buying from abroad explains each of them. This page adds only what changes when you live in the Netherlands.', es: 'Comparar promociones, planos y calendarios de pago, incluso una presentación privada de un proyecto: todo ello se hace a distancia. Las partes que implican al Estado español son un número fiscal, un poder notarial y el origen de sus fondos, y nuestra guía general para comprar desde el extranjero explica cada uno de ellos. Esta página añade únicamente lo que cambia si usted vive en los Países Bajos.', fr: 'Comparer des programmes, des plans et des échéanciers de paiement, même une présentation privée d’un projet : tout cela se fait à distance. Les démarches qui engagent l’État espagnol sont un numéro fiscal, une procuration et l’origine de vos fonds, et notre guide général sur l’achat depuis l’étranger explique chacun de ces points. Cette page n’ajoute que ce qui change lorsque vous vivez aux Pays-Bas.', de: 'Projekte vergleichen, Grundrisse und Zahlungspläne prüfen, sogar eine private Projektpräsentation: all das geht aus der Ferne. Die Teile, an denen der spanische Staat beteiligt ist, sind eine Steuernummer, eine Vollmacht und die Herkunft Ihrer Mittel, und unser allgemeiner Leitfaden zum Kauf aus dem Ausland erklärt jeden dieser Punkte. Diese Seite ergänzt nur, was sich ändert, wenn Sie in den Niederlanden leben.', ru: 'Сравнение проектов, планировок и графиков платежей, даже частная презентация объекта — всё это происходит дистанционно. С испанским государством связаны налоговый номер, доверенность и происхождение ваших средств; наше общее руководство по покупке из-за рубежа объясняет каждый из этих пунктов. Эта страница добавляет лишь то, что меняется, если вы живёте в Нидерландах.', ar: 'مقارنة المشاريع والمخططات وجداول الدفع، بل حتى العرض الخاص لمشروع ما، كل ذلك يجري عن بُعد. أما الأجزاء التي تتصل بالدولة الإسبانية فهي الرقم الضريبي والتوكيل ومصدر أموالك، ويشرح دليلنا العام للشراء من الخارج كلاً منها. وتضيف هذه الصفحة فقط ما يتغيّر حين تقيم في هولندا.', nl: 'Projecten, plattegronden en betaalschema’s vergelijken, zelfs een privépresentatie van een project: het gebeurt allemaal op afstand. De onderdelen waarbij de Spaanse staat betrokken is, zijn een fiscaal nummer, een volmacht en de herkomst van uw geld, en onze algemene gids over kopen vanuit het buitenland legt elk daarvan uit. Deze pagina voegt alleen toe wat verandert als u in Nederland woont.', pl: 'Porównywanie projektów, rzutów i harmonogramów płatności, a nawet prywatna prezentacja inwestycji — wszystko to odbywa się zdalnie. Z udziałem państwa hiszpańskiego wiążą się numer podatkowy, pełnomocnictwo i pochodzenie środków, a każde z nich wyjaśnia nasz ogólny przewodnik po zakupie z zagranicy. Ta strona dodaje wyłącznie to, co zmienia się, gdy mieszkają Państwo w Holandii.', sv: 'Att jämföra projekt, planritningar och betalningsplaner, till och med en privat presentation av ett projekt, sker allt på distans. Det som berör den spanska staten är ett skattenummer, en fullmakt och medlens ursprung, och vår allmänna guide till att köpa från utlandet förklarar var och en av dem. Den här sidan tillför bara det som ändras när ni bor i Nederländerna.', no: 'Å sammenligne prosjekter, plantegninger og betalingsplaner, til og med en privat presentasjon av et prosjekt, skjer alt på avstand. Det som berører den spanske staten, er et skattenummer, en fullmakt og midlenes opprinnelse, og den generelle guiden vår om å kjøpe fra utlandet forklarer hver av dem. Denne siden legger bare til det som endrer seg når du bor i Nederland.' },
  { find: 'Ask About Buying From the Netherlands', es: 'Consúltenos sobre la compra desde los Países Bajos', fr: 'Interrogez-nous sur l’achat depuis les Pays-Bas', de: 'Fragen Sie uns zum Kauf aus den Niederlanden', ru: 'Задать вопрос о покупке из Нидерландов', ar: 'اسأل عن الشراء من هولندا', nl: 'Stel een vraag over kopen vanuit Nederland', pl: 'Zapytaj o zakup z Holandii', sv: 'Fråga om att köpa från Nederländerna', no: 'Spør om å kjøpe fra Nederland' },
  { find: 'Buying From Abroad: The General Guide', es: 'Comprar desde el extranjero: la guía general', fr: 'Acheter depuis l’étranger : le guide général', de: 'Kauf aus dem Ausland: der allgemeine Leitfaden', ru: 'Покупка из-за рубежа: общее руководство', ar: 'الشراء من الخارج: الدليل العام', nl: 'Kopen vanuit het buitenland: de algemene gids', pl: 'Zakup z zagranicy: przewodnik ogólny', sv: 'Köpa från utlandet: den allmänna guiden', no: 'Kjøpe fra utlandet: den generelle guiden' },
  { find: 'Applied for in Amsterdam, <em>in person or through a representative</em>', es: 'Se solicita en Ámsterdam, <em>en persona o por medio de un representante</em>', fr: 'Demandé à Amsterdam, <em>en personne ou par l’intermédiaire d’un représentant</em>', de: 'In Amsterdam beantragt, <em>persönlich oder über einen Vertreter</em>', ru: 'Подаётся в Амстердаме, <em>лично или через представителя</em>', ar: 'يُقدَّم الطلب في أمستردام، <em>شخصياً أو عبر ممثّل</em>', nl: 'Aangevraagd in Amsterdam, <em>persoonlijk of via een vertegenwoordiger</em>', pl: 'Wniosek w Amsterdamie, <em>osobiście lub przez pełnomocnika</em>', sv: 'Ansökan i Amsterdam, <em>personligen eller genom ett ombud</em>', no: 'Søknad i Amsterdam, <em>personlig eller gjennom en representant</em>' },
  { find: 'From the Netherlands, an NIE is applied for at the Spanish Consulate General in Amsterdam. The consulate takes applications from people who will be in Spain for less than three months and have an economic, social or professional interest there, and a property purchase is the example it gives. Anyone moving to live in Spain applies in Spain instead.', es: 'Desde los Países Bajos, el NIE se solicita en el Consulado General de España en Ámsterdam. El consulado admite solicitudes de quienes permanecerán en España menos de tres meses y tienen allí un interés económico, social o profesional, y la compra de un inmueble es el ejemplo que da. Quien vaya a trasladarse a vivir a España lo solicita, en cambio, en España.', fr: 'Depuis les Pays-Bas, le NIE se demande au Consulat général d’Espagne à Amsterdam. Le consulat reçoit les demandes des personnes qui séjourneront en Espagne moins de trois mois et y ont un intérêt économique, social ou professionnel, et l’achat d’un bien immobilier est l’exemple qu’il donne. Toute personne qui s’installe en Espagne pour y vivre fait sa demande en Espagne.', de: 'Aus den Niederlanden wird die NIE beim Spanischen Generalkonsulat in Amsterdam beantragt. Das Konsulat nimmt Anträge von Personen entgegen, die sich weniger als drei Monate in Spanien aufhalten werden und dort ein wirtschaftliches, soziales oder berufliches Interesse haben; als Beispiel nennt es den Immobilienkauf. Wer nach Spanien zieht, um dort zu leben, beantragt sie stattdessen in Spanien.', ru: 'Из Нидерландов NIE оформляется в Генеральном консульстве Испании в Амстердаме. Консульство принимает заявления от тех, кто пробудет в Испании менее трёх месяцев и имеет там экономический, социальный или профессиональный интерес; покупка недвижимости — пример, который оно само приводит. Тот, кто переезжает жить в Испанию, подаёт заявление уже в Испании.', ar: 'من هولندا، يُقدَّم طلب رقم NIE لدى القنصلية العامة لإسبانيا في أمستردام. وتقبل القنصلية الطلبات من الأشخاص الذين سيقيمون في إسبانيا أقل من ثلاثة أشهر ولهم فيها مصلحة اقتصادية أو اجتماعية أو مهنية، وشراء العقار هو المثال الذي تذكره. أما من ينتقل للعيش في إسبانيا فيقدّم طلبه داخل إسبانيا.', nl: 'Vanuit Nederland vraagt u een NIE aan bij het Spaanse consulaat-generaal in Amsterdam. Het consulaat neemt aanvragen in behandeling van mensen die korter dan drie maanden in Spanje zullen zijn en daar een economisch, sociaal of beroepsmatig belang hebben, en de aankoop van een woning is het voorbeeld dat het zelf noemt. Wie naar Spanje verhuist om er te wonen, doet de aanvraag in plaats daarvan in Spanje.', pl: 'Z Holandii o numer NIE występuje się w Konsulacie Generalnym Hiszpanii w Amsterdamie. Konsulat przyjmuje wnioski od osób, które będą przebywać w Hiszpanii krócej niż trzy miesiące i mają tam interes gospodarczy, społeczny lub zawodowy, a zakup nieruchomości jest przykładem, który sam podaje. Kto przeprowadza się do Hiszpanii, składa wniosek w Hiszpanii.', sv: 'Från Nederländerna ansöker man om NIE vid Spaniens generalkonsulat i Amsterdam. Konsulatet tar emot ansökningar från personer som kommer att vistas i Spanien kortare tid än tre månader och har ett ekonomiskt, socialt eller yrkesmässigt intresse där, och ett fastighetsköp är det exempel som konsulatet själv anger. Den som flyttar till Spanien ansöker i stället i Spanien.', no: 'Fra Nederland søkes det om NIE ved Spanias generalkonsulat i Amsterdam. Konsulatet tar imot søknader fra personer som skal oppholde seg i Spania i mindre enn tre måneder og har en økonomisk, sosial eller yrkesmessig interesse der, og et eiendomskjøp er eksemplet konsulatet selv oppgir. Den som flytter til Spania, søker i stedet i Spania.' },
  { find: 'A representative needs a power of attorney that expressly authorises the NIE application. That is worth checking in the wording before the power is signed, because a power drawn for the purchase alone may not say it. The application also asks for the reason behind it, and for a purchase that means evidence of the purchase. Which document the consulate accepts is for the consulate to say, so ask before you book rather than at the desk.', es: 'Un representante necesita un poder que autorice expresamente la solicitud del NIE. Conviene comprobarlo en el texto antes de firmar el poder, porque uno redactado solo para la compra puede no recogerlo. La solicitud también pide el motivo, y en el caso de una compra eso significa acreditar la compra. Qué documento acepta el consulado lo dice el consulado, así que pregunte antes de pedir cita y no en la ventanilla.', fr: 'Un représentant a besoin d’une procuration qui autorise expressément la demande de NIE. Il vaut la peine de le vérifier dans le libellé avant la signature, car une procuration rédigée pour le seul achat peut ne pas le prévoir. La demande exige aussi d’en indiquer le motif, et pour un achat cela suppose un justificatif de l’achat. Le document que le consulat accepte, c’est au consulat de le dire : demandez donc avant de prendre rendez-vous plutôt qu’au guichet.', de: 'Ein Vertreter braucht eine Vollmacht, die ausdrücklich zur Beantragung der NIE ermächtigt. Das sollten Sie im Wortlaut prüfen, bevor die Vollmacht unterzeichnet wird, denn eine allein für den Kauf aufgesetzte Vollmacht enthält dies möglicherweise nicht. Der Antrag verlangt außerdem den Grund, und bei einem Kauf bedeutet das einen Nachweis über den Kauf. Welches Dokument das Konsulat akzeptiert, entscheidet das Konsulat; fragen Sie also vor der Terminbuchung nach und nicht erst am Schalter.', ru: 'Представителю нужна доверенность, которая прямо уполномочивает на подачу заявления на NIE. Это стоит проверить по тексту до подписания, поскольку доверенность, составленная только для покупки, может этого не предусматривать. В заявлении также указывается причина, а при покупке это означает подтверждение самой покупки. Какой документ принимается, решает консульство, поэтому спрашивайте до записи, а не у окошка.', ar: 'يحتاج الممثّل إلى توكيل يخوّله صراحةً تقديم طلب رقم NIE. ويستحق ذلك التحقق من صياغة التوكيل قبل توقيعه، لأن توكيلاً معدّاً للشراء وحده قد لا ينصّ عليه. كما يسأل الطلب عن السبب الكامن وراءه، وهو في حالة الشراء دليل على عملية الشراء. وأيّ مستند تقبله القنصلية أمر تحدده القنصلية، فاسأل قبل أن تحجز الموعد لا عند الشباك.', nl: 'Een vertegenwoordiger heeft een volmacht nodig die de NIE-aanvraag uitdrukkelijk toestaat. Dat is de moeite waard om in de tekst te controleren voordat de volmacht wordt getekend, want een volmacht die alleen voor de aankoop is opgesteld, vermeldt dit mogelijk niet. De aanvraag vraagt ook naar de reden, en bij een aankoop betekent dat bewijs van de aankoop. Welk document het consulaat accepteert, bepaalt het consulaat zelf; vraag het dus voordat u een afspraak boekt en niet aan het loket.', pl: 'Pełnomocnik potrzebuje pełnomocnictwa, które wyraźnie upoważnia do złożenia wniosku o NIE. Warto to sprawdzić w treści, zanim pełnomocnictwo zostanie podpisane, ponieważ dokument sporządzony wyłącznie na potrzeby zakupu może tego nie zawierać. We wniosku podaje się też jego powód, a w przypadku zakupu oznacza to dowód zakupu. To, jaki dokument konsulat przyjmie, rozstrzyga konsulat, więc proszę zapytać przed rezerwacją terminu, a nie przy okienku.', sv: 'Ett ombud behöver en fullmakt som uttryckligen ger rätt att ansöka om NIE. Det är värt att kontrollera i formuleringen innan fullmakten undertecknas, eftersom en fullmakt som upprättats enbart för köpet kanske inte säger det. Ansökan anger också skälet till den, och för ett köp innebär det underlag för köpet. Vilket dokument konsulatet godtar är konsulatets sak att avgöra, så fråga innan ni bokar tid i stället för vid disken.', no: 'En representant trenger en fullmakt som uttrykkelig gir rett til å søke om NIE. Det er verdt å kontrollere ordlyden før fullmakten signeres, siden en fullmakt som er utarbeidet kun for selve kjøpet, kanskje ikke sier det. Søknaden krever også at du oppgir grunnen, og for et kjøp betyr det dokumentasjon på kjøpet. Hvilket dokument konsulatet godtar, er det konsulatet som avgjør, så spør før du bestiller time, ikke i skranken.' },
  { find: '<h3>Where</h3>', es: '<h3>Dónde</h3>', fr: '<h3>Où</h3>', de: '<h3>Wo</h3>', ru: '<h3>Где</h3>', ar: '<h3>أين</h3>', nl: '<h3>Waar</h3>', pl: '<h3>Gdzie</h3>', sv: '<h3>Var</h3>', no: '<h3>Hvor</h3>' },
  { find: 'The Spanish Consulate General in Amsterdam, for a stay of under three months with a stated interest in Spain. A move to Spain follows a different route.', es: 'El Consulado General de España en Ámsterdam, para una estancia de menos de tres meses con un interés declarado en España. Un traslado a España sigue otra vía.', fr: 'Le Consulat général d’Espagne à Amsterdam, pour un séjour de moins de trois mois avec un intérêt déclaré en Espagne. Une installation en Espagne suit une autre voie.', de: 'Das Spanische Generalkonsulat in Amsterdam, für einen Aufenthalt von unter drei Monaten mit einem angegebenen Interesse an Spanien. Ein Umzug nach Spanien folgt einem anderen Weg.', ru: 'Генеральное консульство Испании в Амстердаме — для пребывания менее трёх месяцев при заявленном интересе к Испании. Переезд в Испанию идёт другим путём.', ar: 'القنصلية العامة لإسبانيا في أمستردام، لإقامة تقل عن ثلاثة أشهر مع مصلحة معلنة في إسبانيا. أما الانتقال إلى إسبانيا فيتبع مساراً مختلفاً.', nl: 'Het Spaanse consulaat-generaal in Amsterdam, voor een verblijf van minder dan drie maanden met een aangegeven belang in Spanje. Een verhuizing naar Spanje volgt een andere route.', pl: 'Konsulat Generalny Hiszpanii w Amsterdamie, przy pobycie krótszym niż trzy miesiące i podanym interesie w Hiszpanii. Przeprowadzka do Hiszpanii wiąże się z inną procedurą.', sv: 'Spaniens generalkonsulat i Amsterdam, för en vistelse på under tre månader med ett angivet intresse i Spanien. En flytt till Spanien följer en annan väg.', no: 'Spanias generalkonsulat i Amsterdam, for opphold på under tre måneder med en oppgitt interesse i Spania. En flytting til Spania følger en annen vei.' },
  { find: '<h3>In person</h3>', es: '<h3>En persona</h3>', fr: '<h3>En personne</h3>', de: '<h3>Persönlich</h3>', ru: '<h3>Лично</h3>', ar: '<h3>شخصياً</h3>', nl: '<h3>Persoonlijk</h3>', pl: '<h3>Osobiście</h3>', sv: '<h3>Personligen</h3>', no: '<h3>Personlig</h3>' },
  { find: 'The applicant or a representative must always attend, and an appointment has to be booked through the consulate.', es: 'Siempre debe acudir el solicitante o un representante, y la cita debe reservarse a través del consulado.', fr: 'Le demandeur ou un représentant doit toujours se présenter, et un rendez-vous doit être pris auprès du consulat.', de: 'Es muss immer der Antragsteller oder ein Vertreter erscheinen, und ein Termin muss über das Konsulat gebucht werden.', ru: 'Всегда должен явиться заявитель или представитель, а запись нужно оформить через консульство.', ar: 'يجب أن يحضر مقدّم الطلب أو ممثّله دائماً، ويجب حجز موعد عبر القنصلية.', nl: 'De aanvrager of een vertegenwoordiger moet altijd aanwezig zijn, en er moet via het consulaat een afspraak worden geboekt.', pl: 'Zawsze musi stawić się wnioskodawca albo pełnomocnik, a termin trzeba zarezerwować przez konsulat.', sv: 'Den sökande eller ett ombud måste alltid infinna sig, och en tid måste bokas via konsulatet.', no: 'Søkeren eller en representant må alltid møte opp, og time må bestilles via konsulatet.' },
  { find: '<h3>What it asks for</h3>', es: '<h3>Qué se pide</h3>', fr: '<h3>Ce qui est demandé</h3>', de: '<h3>Was verlangt wird</h3>', ru: '<h3>Что требуется</h3>', ar: '<h3>ما الذي يُطلَب</h3>', nl: '<h3>Wat er gevraagd wordt</h3>', pl: '<h3>Czego wymaga</h3>', sv: '<h3>Vad som krävs</h3>', no: '<h3>Hva det krever</h3>' },
  { find: 'An application stating the reason, proof that you live in the Netherlands, your passport or, for EU nationals, your identity card, and evidence of the purchase.', es: 'Una solicitud en la que conste el motivo, justificante de que reside en los Países Bajos, su pasaporte o, para nacionales de la UE, su documento de identidad, y acreditación de la compra.', fr: 'Une demande indiquant le motif, un justificatif de votre résidence aux Pays-Bas, votre passeport ou, pour les ressortissants de l’UE, votre carte d’identité, et une preuve de l’achat.', de: 'Ein Antrag mit Angabe des Grundes, ein Nachweis, dass Sie in den Niederlanden wohnen, Ihr Reisepass oder, für EU-Staatsangehörige, Ihr Personalausweis, sowie ein Nachweis über den Kauf.', ru: 'Заявление с указанием причины, подтверждение проживания в Нидерландах, паспорт или, для граждан ЕС, удостоверение личности, а также подтверждение покупки.', ar: 'طلب يبيّن السبب، وإثبات إقامتك في هولندا، وجواز سفرك أو بطاقة هويتك إن كنت من مواطني الاتحاد الأوروبي، ودليل على الشراء.', nl: 'Een aanvraag met vermelding van de reden, bewijs dat u in Nederland woont, uw paspoort of, voor EU-onderdanen, uw identiteitskaart, en bewijs van de aankoop.', pl: 'Wniosek z podaniem powodu, dowód zamieszkania w Holandii, paszport lub — w przypadku obywateli UE — dowód osobisty oraz dokument potwierdzający zakup.', sv: 'En ansökan som anger skälet, bevis på att ni bor i Nederländerna, ert pass eller, för EU-medborgare, ert identitetskort, samt underlag för köpet.', no: 'En søknad som oppgir grunnen, bevis på at du bor i Nederland, passet ditt eller, for EU-borgere, ID-kortet ditt, og dokumentasjon på kjøpet.' },
  { find: '<span class="label">From Home</span>', es: '<span class="label">Desde casa</span>', fr: '<span class="label">Depuis chez vous</span>', de: '<span class="label">Von zu Hause aus</span>', ru: '<span class="label">Не выезжая из дома</span>', ar: '<span class="label">من بلدك</span>', nl: '<span class="label">Vanuit huis</span>', pl: '<span class="label">Z domu</span>', sv: '<span class="label">Hemifrån</span>', no: '<span class="label">Hjemmefra</span>' },
  { find: 'What can stay <em>in the Netherlands</em>', es: 'Lo que puede quedarse <em>en los Países Bajos</em>', fr: 'Ce qui peut rester <em>aux Pays-Bas</em>', de: 'Was <em>in den Niederlanden</em> bleiben kann', ru: 'Что можно оставить <em>в Нидерландах</em>', ar: 'ما الذي يمكن أن يبقى <em>في هولندا</em>', nl: 'Wat u kunt regelen <em>vanuit Nederland</em>', pl: 'Co może zostać <em>w Holandii</em>', sv: 'Vad som kan stanna <em>i Nederländerna</em>', no: 'Hva som kan bli <em>i Nederland</em>' },
  { find: 'Reviewing projects, price lists and payment schedules, a private presentation online, reserving a home and instructing a lawyer all happen from where you live. A power of attorney can be signed before a notary in the Netherlands, though one signed outside Spain generally has to be legalised and translated for use there, which adds time rather than difficulty.', es: 'Revisar promociones, listas de precios y calendarios de pago, una presentación privada en línea, reservar una vivienda y contratar a un abogado: todo ello se hace desde donde usted vive. Un poder puede firmarse ante notario en los Países Bajos, aunque uno firmado fuera de España suele tener que legalizarse y traducirse para su uso allí, lo que añade tiempo, no dificultad.', fr: 'Examiner des programmes, des listes de prix et des échéanciers de paiement, assister à une présentation privée en ligne, réserver un logement et mandater un avocat : tout cela se fait depuis votre lieu de résidence. Une procuration peut être signée devant un notaire aux Pays-Bas, mais une procuration signée hors d’Espagne doit généralement être légalisée et traduite pour y être utilisée, ce qui ajoute du temps, non de la difficulté.', de: 'Projekte, Preislisten und Zahlungspläne prüfen, eine private Online-Präsentation, die Reservierung einer Immobilie und die Beauftragung eines Anwalts: all das geschieht von Ihrem Wohnort aus. Eine Vollmacht kann bei einem Notar in den Niederlanden unterzeichnet werden, wobei eine außerhalb Spaniens unterzeichnete Vollmacht für die Verwendung dort in der Regel legalisiert und übersetzt werden muss, was zusätzliche Zeit kostet, den Vorgang aber nicht schwieriger macht.', ru: 'Изучение проектов, прайс-листов и графиков платежей, частная онлайн-презентация, бронирование жилья и поручение юристу — всё это делается по месту вашего проживания. Доверенность можно подписать у нотариуса в Нидерландах, хотя подписанную за пределами Испании, как правило, нужно легализовать и перевести для использования там, и это добавляет времени, а не сложности.', ar: 'مراجعة المشاريع وقوائم الأسعار وجداول الدفع، وعرض خاص عبر الإنترنت، وحجز منزل، وتكليف محامٍ، كل ذلك يجري من مكان إقامتك. ويمكن توقيع التوكيل أمام موثّق في هولندا، غير أن التوكيل الموقَّع خارج إسبانيا يحتاج عموماً إلى تصديق وترجمة ليُستعمل هناك، وهذا يضيف وقتاً لا صعوبة.', nl: 'Projecten, prijslijsten en betaalschema’s bekijken, online een privépresentatie volgen, een woning reserveren en een advocaat inschakelen: dat alles gebeurt vanuit uw woonplaats. Een volmacht kunt u bij een notaris in Nederland laten tekenen, al moet een volmacht die buiten Spanje is getekend over het algemeen worden gelegaliseerd en vertaald om daar te kunnen worden gebruikt; dat kost extra tijd, maar maakt het niet moeilijker.', pl: 'Przegląd projektów, cenników i harmonogramów płatności, prywatna prezentacja online, rezerwacja nieruchomości i zlecenie sprawy prawnikowi — wszystko to odbywa się z miejsca zamieszkania. Pełnomocnictwo można podpisać przed notariuszem w Holandii, choć podpisane poza Hiszpanią zwykle musi zostać zalegalizowane i przetłumaczone do użytku w Hiszpanii, co wydłuża czas, ale nie komplikuje sprawy.', sv: 'Att gå igenom projekt, prislistor och betalningsplaner, en privat presentation online, att reservera en bostad och att anlita en jurist sker allt där ni bor. En fullmakt kan undertecknas inför notarie i Nederländerna, men en fullmakt som undertecknats utanför Spanien måste i regel legaliseras och översättas för att kunna användas där, vilket tar tid snarare än att göra det svårare.', no: 'Å gå gjennom prosjekter, prislister og betalingsplaner, en privat presentasjon på nett, å reservere en bolig og å engasjere en advokat kan alt gjøres der du bor. En fullmakt kan signeres hos en notarius i Nederland, men en fullmakt som er signert utenfor Spania, må som regel legaliseres og oversettes for å kunne brukes der, noe som tar tid snarere enn å gjøre det vanskeligere.' },
  { find: 'What that involves', es: 'En qué consiste', fr: 'Ce que cela implique', de: 'Was das umfasst', ru: 'Что это включает', ar: 'ما الذي يتضمنه ذلك', nl: 'Wat dat inhoudt', pl: 'Co to oznacza', sv: 'Vad det innebär', no: 'Hva det innebærer' },
  { find: 'Two moments still repay a trip more than any document does: seeing the setting at the hours you would actually be there, and the handover walkthrough where defects are written down.', es: 'Dos momentos siguen compensando un viaje más que cualquier documento: ver el entorno a las horas en que usted estaría realmente allí, y el recorrido de la entrega en el que se anotan los defectos.', fr: 'Deux moments valent encore un déplacement plus que n’importe quel document : voir le cadre aux heures où vous y seriez réellement, et la visite de livraison au cours de laquelle les défauts sont consignés.', de: 'Zwei Momente lohnen eine Reise nach wie vor mehr als jedes Dokument: die Umgebung zu den Stunden zu sehen, zu denen Sie tatsächlich dort wären, und den Übergaberundgang, bei dem Mängel schriftlich festgehalten werden.', ru: 'Две вещи по-прежнему оправдывают поездку больше любого документа: увидеть место в те часы, когда вы реально там будете, и осмотр при передаче объекта, на котором фиксируются недочёты.', ar: 'ما زالت هناك لحظتان تستحقان الرحلة أكثر من أي مستند: رؤية المكان في الساعات التي ستكون فيه فعلاً، وجولة التسلّم التي تُدوَّن فيها العيوب.', nl: 'Twee momenten zijn een reis nog altijd meer waard dan welk document ook: de omgeving zien op de uren waarop u er werkelijk zult zijn, en de rondgang bij de oplevering, waarbij gebreken worden vastgelegd.', pl: 'Dwa momenty nadal bardziej niż jakikolwiek dokument wynagradzają podróż: obejrzenie otoczenia w godzinach, w których faktycznie Państwo tam będą, oraz obchód podczas odbioru, podczas którego spisuje się usterki.', sv: 'Två tillfällen betalar fortfarande tillbaka en resa bättre än något dokument: att se miljön vid de tider då ni faktiskt skulle vara där, och genomgången vid tillträdet där fel skrivs ned.', no: 'To øyeblikk betaler fortsatt tilbake en reise bedre enn noe dokument: å se omgivelsene på de tidene du faktisk ville være der, og befaringen ved overtakelsen der mangler føres i protokoll.' },
  { find: 'Why the handover date matters', es: 'Por qué importa la fecha de la entrega', fr: 'Pourquoi la date de livraison compte', de: 'Warum das Übergabedatum zählt', ru: 'Почему важна дата передачи объекта', ar: 'لماذا يهمّ موعد التسلّم', nl: 'Waarom de opleverdatum ertoe doet', pl: 'Dlaczego data odbioru ma znaczenie', sv: 'Varför datumet för tillträdet spelar roll', no: 'Hvorfor datoen for overtakelsen er viktig' },
  { find: '<span class="label">Spanish Tax</span>', es: '<span class="label">Impuestos en España</span>', fr: '<span class="label">Fiscalité espagnole</span>', de: '<span class="label">Steuern in Spanien</span>', ru: '<span class="label">Налоги в Испании</span>', ar: '<span class="label">الضرائب في إسبانيا</span>', nl: '<span class="label">Spaanse belasting</span>', pl: '<span class="label">Podatki w Hiszpanii</span>', sv: '<span class="label">Spansk skatt</span>', no: '<span class="label">Spansk skatt</span>' },
  { find: 'What Spain charges <em>a non-resident owner</em>', es: 'Lo que España cobra <em>a un propietario no residente</em>', fr: 'Ce que l’Espagne prélève <em>sur un propriétaire non résident</em>', de: 'Was Spanien <em>von einem nicht ansässigen Eigentümer</em> verlangt', ru: 'Что Испания взимает <em>с владельца-нерезидента</em>', ar: 'ما الذي تفرضه إسبانيا <em>على مالك غير مقيم</em>', nl: 'Wat Spanje heft van <em>een niet-ingezeten eigenaar</em>', pl: 'Co Hiszpania pobiera od <em>właściciela będącego nierezydentem</em>', sv: 'Vad Spanien tar ut av <em>en icke-bosatt ägare</em>', no: 'Hva Spania krever av <em>en ikke-bosatt eier</em>' },
  { find: 'A non-resident who owns a home in Spain pays Spanish non-resident income tax on it every year, including when it is never rented. For a home that is not let, the Spanish tax agency calculates it on a percentage of the property&rsquo;s cadastral value, with no expenses deducted, and the owner declares it to the agency. Rates and filing dates are set by the agency and change, so we do not quote them here.', es: 'Un no residente que posee una vivienda en España paga cada año por ella el impuesto sobre la renta de no residentes (IRNR), incluso cuando nunca la alquila. Para una vivienda que no se alquila, la Agencia Tributaria lo calcula sobre un porcentaje del valor catastral del inmueble, sin deducir gastos, y el propietario lo declara ante la Agencia. Los tipos y las fechas de presentación los fija la Agencia y cambian, por lo que no los citamos aquí.', fr: 'Un non-résident qui possède un logement en Espagne paie chaque année l’impôt espagnol sur le revenu des non-résidents à ce titre, y compris lorsqu’il ne le loue jamais. Pour un logement qui n’est pas loué, l’administration fiscale espagnole le calcule sur un pourcentage de la valeur cadastrale du bien, sans déduction de frais, et le propriétaire le déclare auprès de cette administration. Les taux et les dates de déclaration sont fixés par l’administration et évoluent ; nous ne les indiquons donc pas ici.', de: 'Wer nicht in Spanien ansässig ist und dort eine Immobilie besitzt, zahlt dafür jedes Jahr die spanische Einkommensteuer für Nichtansässige, auch wenn sie nie vermietet wird. Bei einer nicht vermieteten Immobilie berechnet die spanische Steuerbehörde sie auf Grundlage eines Prozentsatzes des Katasterwerts der Immobilie, ohne Abzug von Ausgaben, und der Eigentümer erklärt sie gegenüber der Behörde. Sätze und Abgabefristen legt die Behörde fest und sie ändern sich, deshalb nennen wir sie hier nicht.', ru: 'Нерезидент, владеющий жильём в Испании, ежегодно платит с него испанский подоходный налог нерезидента, в том числе когда жильё никогда не сдаётся. Для жилья, которое не сдаётся, налоговое ведомство Испании рассчитывает его как процент от кадастровой стоимости объекта без вычета расходов, а владелец подаёт декларацию в это ведомство. Ставки и сроки подачи устанавливает ведомство, и они меняются, поэтому мы их здесь не приводим.', ar: 'يدفع غير المقيم الذي يملك منزلاً في إسبانيا ضريبة دخل لغير المقيمين عنه كل عام، حتى حين لا يؤجَّر أبداً. وفي المنزل غير المؤجَّر تحتسبها الإدارة الضريبية الإسبانية على نسبة مئوية من القيمة الكاداسترية للعقار دون خصم أي نفقات، ويقدّم المالك إقراره بها إلى الإدارة. وتحدد الإدارة النسب ومواعيد التقديم وهي تتغيّر، لذلك لا نذكرها هنا.', nl: 'Een niet-ingezetene die een woning in Spanje bezit, betaalt daarover elk jaar Spaanse inkomstenbelasting voor niet-ingezetenen, ook als de woning nooit wordt verhuurd. Voor een woning die niet wordt verhuurd berekent de Spaanse belastingdienst die belasting over een percentage van de kadastrale waarde van het pand, zonder aftrek van kosten, en de eigenaar doet daarvan aangifte bij de belastingdienst. Tarieven en aangiftedata worden door de belastingdienst bepaald en veranderen, dus we noemen ze hier niet.', pl: 'Nierezydent, który posiada w Hiszpanii nieruchomość, co roku płaci od niej hiszpański podatek dochodowy od nierezydentów, także wtedy, gdy nigdy jej nie wynajmuje. W przypadku nieruchomości niewynajmowanej hiszpański urząd podatkowy oblicza go jako procent wartości katastralnej nieruchomości, bez odliczania kosztów, a właściciel składa deklarację w tym urzędzie. Stawki i terminy składania deklaracji ustala ten urząd i ulegają one zmianom, dlatego nie podajemy ich tutaj.', sv: 'En icke-bosatt som äger en bostad i Spanien betalar varje år spansk inkomstskatt för icke-bosatta på den, även när den aldrig hyrs ut. För en bostad som inte hyrs ut beräknar den spanska skattemyndigheten skatten på en procentsats av fastighetens katastralvärde, utan att några utgifter dras av, och ägaren deklarerar den till myndigheten. Skattesatser och inlämningsdatum fastställs av myndigheten och ändras, så vi anger dem inte här.', no: 'En ikke-bosatt som eier en bolig i Spania, betaler hvert år spansk inntektsskatt for ikke-bosatte på den, også når den aldri leies ut. For en bolig som ikke leies ut, beregner den spanske skattemyndigheten skatten som en prosentandel av eiendommens katastralverdi, uten fradrag for utgifter, og eieren innberetter den til myndigheten. Satser og innleveringsfrister fastsettes av myndigheten og endres, så vi oppgir dem ikke her.' },
  { find: 'The yearly costs of owning, and the costs of buying', es: 'Los costes anuales de ser propietario y los gastos de compra', fr: 'Les coûts annuels de la propriété et les frais d’achat', de: 'Die jährlichen Kosten des Eigentums und die Kaufnebenkosten', ru: 'Ежегодные расходы на содержание и расходы на покупку', ar: 'التكاليف السنوية للتملّك وتكاليف الشراء', nl: 'De jaarlijkse kosten van bezit en de kosten van de aankoop', pl: 'Roczne koszty posiadania oraz koszty zakupu', sv: 'De årliga kostnaderna för att äga, och kostnaderna för att köpa', no: 'De årlige kostnadene ved å eie, og kostnadene ved å kjøpe' },
  { find: '<span class="label">Your Dutch Tax Position</span>', es: '<span class="label">Su situación fiscal en los Países Bajos</span>', fr: '<span class="label">Votre situation fiscale aux Pays-Bas</span>', de: '<span class="label">Ihre steuerliche Situation in den Niederlanden</span>', ru: '<span class="label">Ваше налоговое положение в Нидерландах</span>', ar: '<span class="label">وضعك الضريبي في هولندا</span>', nl: '<span class="label">Uw Nederlandse fiscale positie</span>', pl: '<span class="label">Państwa sytuacja podatkowa w Holandii</span>', sv: '<span class="label">Er skattesituation i Nederländerna</span>', no: '<span class="label">Din skattesituasjon i Nederland</span>' },
  { find: 'The part we <em>deliberately leave out</em>', es: 'La parte que <em>dejamos fuera a propósito</em>', fr: 'Ce que nous <em>laissons volontairement de côté</em>', de: 'Der Teil, den wir <em>bewusst auslassen</em>', ru: 'То, что мы <em>намеренно не затрагиваем</em>', ar: 'الجزء الذي <em>نتركه عمداً</em>', nl: 'Het deel dat wij <em>bewust weglaten</em>', pl: 'Część, którą <em>świadomie pomijamy</em>', sv: 'Det vi <em>medvetet utelämnar</em>', no: 'Den delen vi <em>bevisst utelater</em>' },
  { find: 'How a Spanish home is treated in your Dutch tax return, and how the rules of the two countries interact, depends on your own circumstances and on the tax treaty between the Netherlands and Spain, which can change. We are a property advisory and not a tax adviser, so this page states no rates and no amounts. These are the questions worth taking to a Dutch tax adviser before you sign.', es: 'Cómo se trata una vivienda española en su declaración de impuestos neerlandesa, y cómo interactúan las normas de ambos países, depende de sus circunstancias y del convenio fiscal entre los Países Bajos y España, que puede cambiar. Somos una asesoría inmobiliaria y no asesores fiscales, así que esta página no indica tipos ni importes. Estas son las preguntas que conviene llevar a un asesor fiscal neerlandés antes de firmar.', fr: 'La manière dont un bien espagnol est traité dans votre déclaration fiscale néerlandaise, et dont les règles des deux pays s’articulent, dépend de votre situation personnelle et de la convention fiscale entre les Pays-Bas et l’Espagne, qui peut évoluer. Nous sommes un cabinet de conseil immobilier et non un conseiller fiscal ; cette page n’indique donc ni taux ni montants. Voici les questions à soumettre à un conseiller fiscal néerlandais avant de signer.', de: 'Wie eine spanische Immobilie in Ihrer niederländischen Steuererklärung behandelt wird und wie die Regeln beider Länder ineinandergreifen, hängt von Ihren persönlichen Umständen und vom Steuerabkommen zwischen den Niederlanden und Spanien ab, das sich ändern kann. Wir sind eine Immobilienberatung und kein Steuerberater, deshalb nennt diese Seite weder Sätze noch Beträge. Dies sind die Fragen, die Sie vor der Unterzeichnung einem niederländischen Steuerberater stellen sollten.', ru: 'То, как испанское жильё учитывается в вашей нидерландской налоговой декларации и как взаимодействуют правила двух стран, зависит от ваших обстоятельств и от налогового договора между Нидерландами и Испанией, который может измениться. Мы — консультанты по недвижимости, а не налоговые консультанты, поэтому на этой странице нет ни ставок, ни сумм. Вот вопросы, которые стоит задать нидерландскому налоговому консультанту до подписания.', ar: 'تتوقف طريقة معاملة منزل في إسبانيا في إقرارك الضريبي الهولندي، وكيفية تفاعل قواعد البلدين، على ظروفك الخاصة وعلى الاتفاقية الضريبية بين هولندا وإسبانيا، وهي قابلة للتغيّر. نحن جهة استشارية عقارية ولسنا مستشاراً ضريبياً، لذلك لا تذكر هذه الصفحة نسباً ولا مبالغ. وهذه هي الأسئلة التي يحسن طرحها على مستشار ضريبي هولندي قبل التوقيع.', nl: 'Hoe een Spaanse woning in uw Nederlandse aangifte wordt behandeld, en hoe de regels van de twee landen op elkaar inwerken, hangt af van uw eigen omstandigheden en van het belastingverdrag tussen Nederland en Spanje, dat kan veranderen. Wij zijn een vastgoedadviseur en geen belastingadviseur, daarom noemt deze pagina geen tarieven en geen bedragen. Dit zijn de vragen die u vóór het tekenen aan een Nederlandse belastingadviseur kunt voorleggen.', pl: 'To, jak hiszpańska nieruchomość jest traktowana w Państwa holenderskim zeznaniu podatkowym i jak współdziałają przepisy obu krajów, zależy od Państwa indywidualnej sytuacji oraz od umowy podatkowej między Holandią a Hiszpanią, która może ulec zmianie. Zajmujemy się doradztwem w zakresie nieruchomości, a nie podatkowym, dlatego ta strona nie podaje ani stawek, ani kwot. Oto pytania, z którymi warto zwrócić się do holenderskiego doradcy podatkowego przed podpisaniem umowy.', sv: 'Hur en spansk bostad behandlas i er nederländska deklaration, och hur de båda ländernas regler samspelar, beror på era egna förhållanden och på skatteavtalet mellan Nederländerna och Spanien, som kan ändras. Vi är fastighetsrådgivare och inte skatterådgivare, så den här sidan anger inga skattesatser och inga belopp. Det här är frågorna som är värda att ta med till en nederländsk skatterådgivare innan ni skriver under.', no: 'Hvordan en spansk bolig behandles i selvangivelsen din i Nederland, og hvordan reglene i de to landene samspiller, avhenger av dine egne forhold og av skatteavtalen mellom Nederland og Spania, som kan endres. Vi er eiendomsrådgivere og ikke skatterådgivere, så denne siden oppgir verken satser eller beløp. Dette er spørsmålene det er verdt å ta med til en nederlandsk skatterådgiver før du signerer.' },
  { find: '<h3>Reporting</h3>', es: '<h3>Declaración</h3>', fr: '<h3>Déclaration</h3>', de: '<h3>Deklaration</h3>', ru: '<h3>Декларирование</h3>', ar: '<h3>الإقرار</h3>', nl: '<h3>Aangifte</h3>', pl: '<h3>Deklarowanie</h3>', sv: '<h3>Redovisning</h3>', no: '<h3>Rapportering</h3>' },
  { find: 'Does the home have to be declared in my Dutch return, and under which heading?', es: '¿Debe declararse la vivienda en mi declaración neerlandesa y bajo qué apartado?', fr: 'Le logement doit-il être déclaré dans ma déclaration fiscale néerlandaise, et sous quelle rubrique ?', de: 'Muss die Immobilie in meiner niederländischen Steuererklärung angegeben werden, und unter welcher Rubrik?', ru: 'Нужно ли указывать жильё в моей нидерландской декларации и в каком разделе?', ar: 'هل يجب التصريح بالمنزل في إقراري الضريبي الهولندي، وتحت أي بند؟', nl: 'Moet de woning worden opgegeven in mijn Nederlandse aangifte, en onder welk onderdeel?', pl: 'Czy nieruchomość trzeba wykazać w moim holenderskim zeznaniu podatkowym i w której pozycji?', sv: 'Måste bostaden redovisas i min nederländska deklaration, och under vilken rubrik?', no: 'Må boligen oppgis i selvangivelsen min i Nederland, og under hvilken post?' },
  { find: '<h3>Relief</h3>', es: '<h3>Desgravación</h3>', fr: '<h3>Allègement</h3>', de: '<h3>Entlastung</h3>', ru: '<h3>Льгота</h3>', ar: '<h3>التخفيف</h3>', nl: '<h3>Verlichting</h3>', pl: '<h3>Ulga</h3>', sv: '<h3>Skattelättnad</h3>', no: '<h3>Fradrag</h3>' },
  { find: 'Is any relief for tax paid in Spain applied automatically, or does it have to be claimed?', es: '¿Se aplica automáticamente alguna desgravación por el impuesto pagado en España o hay que solicitarla?', fr: 'Un allègement au titre de l’impôt payé en Espagne s’applique-t-il automatiquement, ou faut-il le demander ?', de: 'Wird eine Entlastung für in Spanien gezahlte Steuern automatisch berücksichtigt, oder muss sie beantragt werden?', ru: 'Применяется ли автоматически льгота в связи с налогом, уплаченным в Испании, или её нужно запрашивать?', ar: 'هل يُطبَّق تلقائياً تخفيف عن الضريبة المدفوعة في إسبانيا، أم يجب طلبه؟', nl: 'Wordt een verlichting voor in Spanje betaalde belasting automatisch toegepast, of moet die worden aangevraagd?', pl: 'Czy ewentualna ulga z tytułu podatku zapłaconego w Hiszpanii stosowana jest automatycznie, czy trzeba o nią wnioskować?', sv: 'Tillämpas eventuell skattelättnad för skatt som betalats i Spanien automatiskt, eller måste den begäras?', no: 'Gis det automatisk fradrag for skatt betalt i Spania, eller må det kreves?' },
  { find: '<h3>The treaty</h3>', es: '<h3>El convenio</h3>', fr: '<h3>La convention</h3>', de: '<h3>Das Abkommen</h3>', ru: '<h3>Договор</h3>', ar: '<h3>الاتفاقية</h3>', nl: '<h3>Het verdrag</h3>', pl: '<h3>Umowa podatkowa</h3>', sv: '<h3>Skatteavtalet</h3>', no: '<h3>Skatteavtalen</h3>' },
  { find: 'Is the treaty between the Netherlands and Spain due to change, and would that affect a home bought now?', es: '¿Está previsto que cambie el convenio entre los Países Bajos y España, y afectaría a una vivienda comprada ahora?', fr: 'La convention entre les Pays-Bas et l’Espagne doit-elle changer, et cela concernerait-il un logement acheté maintenant ?', de: 'Soll sich das Abkommen zwischen den Niederlanden und Spanien ändern, und würde das eine jetzt gekaufte Immobilie betreffen?', ru: 'Предстоит ли изменение договора между Нидерландами и Испанией, и повлияет ли оно на жильё, купленное сейчас?', ar: 'هل من المقرر أن تتغيّر الاتفاقية بين هولندا وإسبانيا، وهل سيؤثر ذلك في منزل يُشترى الآن؟', nl: 'Gaat het verdrag tussen Nederland en Spanje veranderen, en zou dat gevolgen hebben voor een woning die nu wordt gekocht?', pl: 'Czy umowa między Holandią a Hiszpanią ma ulec zmianie i czy wpłynęłoby to na nieruchomość kupioną teraz?', sv: 'Ska avtalet mellan Nederländerna och Spanien ändras, och skulle det påverka en bostad som köps nu?', no: 'Skal avtalen mellom Nederland og Spania endres, og vil det påvirke en bolig som kjøpes nå?' },
  { find: '<h3>Financing</h3>', es: '<h3>Financiación</h3>', fr: '<h3>Financement</h3>', de: '<h3>Finanzierung</h3>', ru: '<h3>Финансирование</h3>', ar: '<h3>التمويل</h3>', nl: '<h3>Financiering</h3>', pl: '<h3>Finansowanie</h3>', sv: '<h3>Finansiering</h3>', no: '<h3>Finansiering</h3>' },
  { find: 'If I borrow to buy, how is the loan treated in my Dutch return?', es: 'Si pido un préstamo para comprar, ¿cómo se trata el préstamo en mi declaración neerlandesa?', fr: 'Si j’emprunte pour acheter, comment le prêt est-il traité dans ma déclaration fiscale néerlandaise ?', de: 'Wenn ich für den Kauf einen Kredit aufnehme, wie wird er in meiner niederländischen Steuererklärung behandelt?', ru: 'Если я беру кредит на покупку, как этот кредит учитывается в моей нидерландской декларации?', ar: 'إذا اقترضت للشراء، فكيف يُعامَل القرض في إقراري الضريبي الهولندي؟', nl: 'Als ik leen om te kopen, hoe wordt de lening dan behandeld in mijn Nederlandse aangifte?', pl: 'Jeśli finansuję zakup kredytem, jak kredyt jest traktowany w moim holenderskim zeznaniu podatkowym?', sv: 'Om jag lånar för att köpa, hur behandlas lånet i min nederländska deklaration?', no: 'Hvis jeg låner for å kjøpe, hvordan behandles lånet i selvangivelsen min i Nederland?' },
  { find: 'Procedure changes, <em>and the consulate&rsquo;s page is the reliable version</em>', es: 'El procedimiento cambia, <em>y la página del consulado es la versión fiable</em>', fr: 'La procédure évolue, <em>et la page du consulat fait foi</em>', de: 'Das Verfahren ändert sich <em>und die Seite des Konsulats ist die verlässliche Fassung</em>', ru: 'Процедура меняется, <em>и надёжна версия на странице консульства</em>', ar: 'الإجراءات تتغيّر، <em>وصفحة القنصلية هي النسخة الموثوقة</em>', nl: 'De procedure verandert, <em>en de pagina van het consulaat is de betrouwbare versie</em>', pl: 'Procedura się zmienia, <em>a wiarygodna jest strona konsulatu</em>', sv: 'Förfarandet ändras, <em>och konsulatets egen sida är den tillförlitliga versionen</em>', no: 'Prosedyren endres, <em>og konsulatets side er den pålitelige versjonen</em>' },
  { find: 'This page describes the NIE route as the consulate publishes it, not the current paperwork. Appointments, documents and requirements change without much notice, and', es: 'Esta página describe la vía del NIE tal como la publica el consulado, no el papeleo vigente. Las citas, los documentos y los requisitos cambian con poco aviso, y', fr: 'Cette page décrit la voie du NIE telle que le consulat la publie, et non les formalités en vigueur. Les rendez-vous, les documents et les exigences changent sans grand préavis, et', de: 'Diese Seite beschreibt den Weg zur NIE so, wie das Konsulat ihn veröffentlicht, nicht die aktuellen Formalitäten. Termine, Unterlagen und Anforderungen ändern sich kurzfristig, und', ru: 'Эта страница описывает порядок получения NIE так, как его публикует консульство, а не действующий перечень документов. Записи, документы и требования меняются без особого предупреждения, а', ar: 'تصف هذه الصفحة مسار رقم NIE كما تنشره القنصلية، لا الأوراق المطلوبة حالياً. فالمواعيد والمستندات والمتطلبات تتغيّر دون إشعار كبير، وأمّا', nl: 'Deze pagina beschrijft de NIE-route zoals het consulaat die publiceert, niet het actuele papierwerk. Afspraken, documenten en vereisten veranderen zonder veel aankondiging, en', pl: 'Ta strona opisuje drogę do NIE tak, jak publikuje ją konsulat, a nie bieżące formalności. Terminy, dokumenty i wymogi zmieniają się bez większego uprzedzenia, a', sv: 'Den här sidan beskriver NIE-vägen så som konsulatet publicerar den, inte det aktuella pappersarbetet. Tider, handlingar och krav ändras utan större förvarning, och', no: 'Denne siden beskriver NIE-veien slik konsulatet publiserer den, ikke det gjeldende papirarbeidet. Timeavtaler, dokumenter og krav endres uten stort varsel, og' },
  { find: 'the consulate&rsquo;s own page', es: 'la página del propio consulado', fr: 'la propre page du consulat', de: 'die eigene Seite des Konsulats', ru: 'собственная страница консульства', ar: 'صفحة القنصلية نفسها', nl: 'de eigen pagina van het consulaat', pl: 'strona samego konsulatu', sv: 'konsulatets egen sida', no: 'konsulatets egen side' },
  { find: 'is the version to follow. Nothing here is legal or tax advice.', es: 'es la versión que debe seguirse. Nada de lo aquí expuesto constituye asesoramiento jurídico ni fiscal.', fr: 'est la version à suivre. Rien ici ne constitue un conseil juridique ou fiscal.', de: 'ist die maßgebliche Fassung. Nichts hierin stellt eine Rechts- oder Steuerberatung dar.', ru: '— версия, которой следует руководствоваться. Ничто здесь не является юридической или налоговой консультацией.', ar: 'فهي النسخة التي ينبغي اتباعها. لا شيء هنا يُعدّ استشارة قانونية أو ضريبية.', nl: 'is de versie die u moet volgen. Niets hierop is juridisch of fiscaal advies.', pl: 'jest wersją, której należy się trzymać. Nic tu zawarte nie stanowi porady prawnej ani podatkowej.', sv: 'är den version man ska följa. Ingenting här utgör juridisk rådgivning eller skatterådgivning.', no: 'er den versjonen du bør følge. Ingenting her er juridisk rådgivning eller skatterådgivning.' },
  { find: 'What Dutch buyers ask us <em>before they start</em>', es: 'Lo que nos preguntan los compradores neerlandeses <em>antes de empezar</em>', fr: 'Ce que les acheteurs néerlandais nous demandent <em>avant de commencer</em>', de: 'Was niederländische Käufer uns fragen, <em>bevor sie beginnen</em>', ru: 'О чём покупатели из Нидерландов спрашивают нас <em>до начала</em>', ar: 'ما الذي يسألنا عنه المشترون الهولنديون <em>قبل أن يبدؤوا</em>', nl: 'Wat Nederlandse kopers ons vragen <em>voordat ze beginnen</em>', pl: 'O co pytają nas kupujący z Holandii <em>zanim zaczną</em>', sv: 'Vad nederländska köpare frågar oss <em>innan de börjar</em>', no: 'Hva nederlandske kjøpere spør oss om <em>før de starter</em>' },
  { find: 'Where do I apply for an NIE if I live in the Netherlands?', es: '¿Dónde solicito el NIE si vivo en los Países Bajos?', fr: 'Où demander un NIE si je vis aux Pays-Bas ?', de: 'Wo beantrage ich die NIE, wenn ich in den Niederlanden lebe?', ru: 'Где подать заявление на NIE, если я живу в Нидерландах?', ar: 'أين أقدّم طلب رقم NIE إذا كنت أقيم في هولندا؟', nl: 'Waar vraag ik een NIE aan als ik in Nederland woon?', pl: 'Gdzie złożyć wniosek o NIE, jeśli mieszkam w Holandii?', sv: 'Var ansöker jag om NIE om jag bor i Nederländerna?', no: 'Hvor søker jeg om NIE hvis jeg bor i Nederland?' },
  { find: 'At the Spanish Consulate General in Amsterdam, by appointment, if you will be in Spain for less than three months and have an economic, social or professional interest there, which a purchase is. If you are moving to Spain, you apply in Spain instead.', es: 'En el Consulado General de España en Ámsterdam, con cita previa, si va a estar en España menos de tres meses y tiene allí un interés económico, social o profesional, y una compra lo es. Si se traslada a España, lo solicita en España.', fr: 'Au Consulat général d’Espagne à Amsterdam, sur rendez-vous, si vous séjournerez en Espagne moins de trois mois et y avez un intérêt économique, social ou professionnel, ce qui est le cas d’un achat. Si vous vous installez en Espagne, vous faites la demande en Espagne.', de: 'Beim Spanischen Generalkonsulat in Amsterdam, nach Terminvereinbarung, wenn Sie sich weniger als drei Monate in Spanien aufhalten werden und dort ein wirtschaftliches, soziales oder berufliches Interesse haben, was bei einem Kauf der Fall ist. Wenn Sie nach Spanien ziehen, beantragen Sie sie stattdessen in Spanien.', ru: 'В Генеральном консульстве Испании в Амстердаме, по записи, если вы пробудете в Испании менее трёх месяцев и имеете там экономический, социальный или профессиональный интерес, каковым является покупка. Если вы переезжаете в Испанию, заявление подаётся уже в Испании.', ar: 'لدى القنصلية العامة لإسبانيا في أمستردام، بموعد، إذا كنت ستقيم في إسبانيا أقل من ثلاثة أشهر ولك فيها مصلحة اقتصادية أو اجتماعية أو مهنية، وهو ما يمثّله الشراء. وإذا كنت تنتقل إلى إسبانيا فتقدّم الطلب داخل إسبانيا.', nl: 'Bij het Spaanse consulaat-generaal in Amsterdam, op afspraak, als u korter dan drie maanden in Spanje zult zijn en daar een economisch, sociaal of beroepsmatig belang hebt, wat bij een aankoop het geval is. Als u naar Spanje verhuist, vraagt u het in plaats daarvan in Spanje aan.', pl: 'W Konsulacie Generalnym Hiszpanii w Amsterdamie, po umówieniu terminu, jeśli będą Państwo przebywać w Hiszpanii krócej niż trzy miesiące i mają tam interes gospodarczy, społeczny lub zawodowy, a zakup nieruchomości takim interesem jest. Jeśli przeprowadzają się Państwo do Hiszpanii, wniosek składa się w Hiszpanii.', sv: 'Vid Spaniens generalkonsulat i Amsterdam, efter tidsbokning, om ni kommer att vistas i Spanien kortare tid än tre månader och har ett ekonomiskt, socialt eller yrkesmässigt intresse där, vilket ett köp är. Flyttar ni till Spanien ansöker ni i stället i Spanien.', no: 'Ved Spanias generalkonsulat i Amsterdam, etter timebestilling, hvis du skal oppholde deg i Spania i mindre enn tre måneder og har en økonomisk, sosial eller yrkesmessig interesse der, noe et kjøp er. Hvis du flytter til Spania, søker du i stedet i Spania.' },
  { find: 'Do I have to go to Amsterdam myself?', es: '¿Tengo que acudir personalmente a Ámsterdam?', fr: 'Dois-je me rendre moi-même à Amsterdam ?', de: 'Muss ich selbst nach Amsterdam fahren?', ru: 'Нужно ли мне самому ехать в Амстердам?', ar: 'هل يجب أن أذهب إلى أمستردام بنفسي؟', nl: 'Moet ik zelf naar Amsterdam?', pl: 'Czy muszę osobiście jechać do Amsterdamu?', sv: 'Måste jag åka till Amsterdam själv?', no: 'Må jeg reise til Amsterdam selv?' },
  { find: 'Either you or a representative has to attend, so there is no remote route. A representative needs a power of attorney that expressly covers the NIE application, which is how buyers avoid the trip.', es: 'Debe acudir usted o un representante, así que no existe una vía a distancia. Un representante necesita un poder que contemple expresamente la solicitud del NIE, que es como los compradores evitan el viaje.', fr: 'Vous ou un représentant devez vous présenter, il n’existe donc pas de démarche à distance. Un représentant a besoin d’une procuration couvrant expressément la demande de NIE, et c’est ainsi que les acheteurs évitent le déplacement.', de: 'Entweder Sie oder ein Vertreter muss erscheinen, einen Fernweg gibt es also nicht. Ein Vertreter braucht eine Vollmacht, die den NIE-Antrag ausdrücklich abdeckt; so ersparen sich Käufer die Reise.', ru: 'Должны явиться либо вы, либо представитель, так что дистанционного пути нет. Представителю нужна доверенность, которая прямо охватывает подачу заявления на NIE, — так покупатели избегают поездки.', ar: 'يجب أن تحضر أنت أو ممثّل عنك، فلا يوجد مسار عن بُعد. ويحتاج الممثّل إلى توكيل يشمل صراحةً طلب رقم NIE، وبذلك يتفادى المشترون الرحلة.', nl: 'U of een vertegenwoordiger moet aanwezig zijn, dus een route op afstand bestaat niet. Een vertegenwoordiger heeft een volmacht nodig die de NIE-aanvraag uitdrukkelijk dekt, en zo besparen kopers zich de reis.', pl: 'Na miejscu musi się stawić albo Pan lub Pani, albo pełnomocnik, więc nie ma drogi zdalnej. Pełnomocnik potrzebuje pełnomocnictwa wyraźnie obejmującego wniosek o NIE i w ten sposób kupujący unikają podróży.', sv: 'Antingen ni själva eller ett ombud måste infinna sig, så det finns ingen väg på distans. Ett ombud behöver en fullmakt som uttryckligen omfattar ansökan om NIE, och så undviker köpare resan.', no: 'Enten du selv eller en representant må møte opp, så det finnes ingen fjernløsning. En representant trenger en fullmakt som uttrykkelig dekker NIE-søknaden, og slik unngår kjøpere reisen.' },
  { find: 'Does a Dutch notary&rsquo;s power of attorney work in Spain?', es: '¿Sirve en España un poder otorgado ante un notario neerlandés?', fr: 'Une procuration établie devant un notaire néerlandais est-elle valable en Espagne ?', de: 'Ist eine vor einem niederländischen Notar erteilte Vollmacht in Spanien gültig?', ru: 'Действует ли в Испании доверенность нидерландского нотариуса?', ar: 'هل يصلح في إسبانيا توكيل صادر عن موثّق هولندي؟', nl: 'Werkt de volmacht van een Nederlandse notaris in Spanje?', pl: 'Czy pełnomocnictwo sporządzone przez holenderskiego notariusza jest skuteczne w Hiszpanii?', sv: 'Fungerar en nederländsk notaries fullmakt i Spanien?', no: 'Fungerer en nederlandsk notarius’ fullmakt i Spania?' },
  { find: 'It can, once it has been legalised and translated for use in Spain. Plan for that step rather than around it, and check that the wording covers what you need it for, the NIE included.', es: 'Puede servir, una vez legalizado y traducido para su uso en España. Planifique ese paso en lugar de intentar esquivarlo, y compruebe que el texto cubre aquello para lo que lo necesita, incluido el NIE.', fr: 'Elle peut l’être, une fois légalisée et traduite pour être utilisée en Espagne. Prévoyez cette étape plutôt que de la contourner, et vérifiez que le libellé couvre ce pour quoi vous en avez besoin, NIE compris.', de: 'Das kann sie sein, sobald sie für die Verwendung in Spanien legalisiert und übersetzt wurde. Planen Sie diesen Schritt ein, statt ihn zu umgehen, und prüfen Sie, ob der Wortlaut abdeckt, wofür Sie sie brauchen, die NIE eingeschlossen.', ru: 'Может действовать, после легализации и перевода для использования в Испании. Планируйте этот шаг, а не пытайтесь его обойти, и проверьте, что текст охватывает то, для чего она нужна, включая NIE.', ar: 'يمكن ذلك بعد تصديقه وترجمته للاستعمال في إسبانيا. خطّط لهذه الخطوة بدل الالتفاف حولها، وتحقق من أن الصياغة تغطي ما تحتاجه، بما في ذلك رقم NIE.', nl: 'Dat kan, nadat zij is gelegaliseerd en vertaald voor gebruik in Spanje. Plan die stap in in plaats van eromheen te werken, en controleer of de tekst dekt waarvoor u de volmacht nodig hebt, het NIE inbegrepen.', pl: 'Może, o ile zostało zalegalizowane i przetłumaczone do użytku w Hiszpanii. Ten krok trzeba zaplanować, a nie go omijać, i sprawdzić, czy treść obejmuje to, do czego pełnomocnictwo ma służyć, w tym NIE.', sv: 'Ja, när den har legaliserats och översatts för användning i Spanien. Planera för det steget i stället för runt det, och kontrollera att formuleringen täcker det ni behöver den till, NIE inräknat.', no: 'Det kan det, når den er legalisert og oversatt for bruk i Spania. Planlegg for det trinnet heller enn rundt det, og kontroller at ordlyden dekker det du trenger den til, NIE inkludert.' },
  { find: 'Does Nueva Living give tax advice to Dutch buyers?', es: '¿Nueva Living ofrece asesoramiento fiscal a compradores neerlandeses?', fr: 'Nueva Living donne-t-elle des conseils fiscaux aux acheteurs néerlandais ?', de: 'Erteilt Nueva Living niederländischen Käufern Steuerberatung?', ru: 'Даёт ли Nueva Living налоговые консультации покупателям из Нидерландов?', ar: 'هل تقدّم Nueva Living استشارات ضريبية للمشترين الهولنديين؟', nl: 'Geeft Nueva Living fiscaal advies aan Nederlandse kopers?', pl: 'Czy Nueva Living udziela porad podatkowych kupującym z Holandii?', sv: 'Ger Nueva Living skatterådgivning till nederländska köpare?', no: 'Gir Nueva Living skatterådgivning til nederlandske kjøpere?' },
  { find: 'No. We advise on the property and the purchase. How a Spanish home is treated in your Dutch tax return is a question for a Dutch tax adviser, and the page above lists what to ask.', es: 'No. Asesoramos sobre la vivienda y la compra. Cómo se trata una vivienda española en su declaración de impuestos neerlandesa es una cuestión para un asesor fiscal neerlandés, y más arriba en esta página se enumera qué preguntar.', fr: 'Non. Nous conseillons sur le bien et sur l’achat. La manière dont un bien espagnol est traité dans votre déclaration fiscale néerlandaise relève d’un conseiller fiscal néerlandais, et la page, plus haut, indique ce qu’il faut demander.', de: 'Nein. Wir beraten zur Immobilie und zum Kauf. Wie eine spanische Immobilie in Ihrer niederländischen Steuererklärung behandelt wird, ist eine Frage für einen niederländischen Steuerberater, und die Seite weiter oben führt auf, was Sie fragen sollten.', ru: 'Нет. Мы консультируем по недвижимости и по самой покупке. Как испанское жильё учитывается в вашей нидерландской налоговой декларации — вопрос к нидерландскому налоговому консультанту, а выше перечислено, о чём спрашивать.', ar: 'لا. نحن نقدّم المشورة في العقار وفي عملية الشراء. أما كيفية معاملة منزل في إسبانيا في إقرارك الضريبي الهولندي فسؤال لمستشار ضريبي هولندي، وقد عدّدت الصفحة أعلاه ما ينبغي سؤاله.', nl: 'Nee. Wij adviseren over het vastgoed en de aankoop. Hoe een Spaanse woning in uw Nederlandse aangifte wordt behandeld, is een vraag voor een Nederlandse belastingadviseur, en de pagina hierboven somt op wat u kunt vragen.', pl: 'Nie. Doradzamy w sprawie nieruchomości i zakupu. To, jak hiszpańska nieruchomość jest traktowana w Państwa holenderskim zeznaniu podatkowym, jest pytaniem do holenderskiego doradcy podatkowego, a strona powyżej wymienia, o co warto zapytać.', sv: 'Nej. Vi ger råd om bostaden och köpet. Hur en spansk bostad behandlas i er nederländska deklaration är en fråga för en nederländsk skatterådgivare, och sidan ovan listar vad ni bör fråga.', no: 'Nei. Vi gir råd om eiendommen og kjøpet. Hvordan en spansk bolig behandles i selvangivelsen din i Nederland, er et spørsmål for en nederlandsk skatterådgiver, og siden ovenfor lister opp hva du bør spørre om.' },
];
